import React, { useState, useEffect, useRef } from 'react';
import { Container, Button, Input, InputGroup, InputGroupText } from 'reactstrap';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';

const ChatRoom = ({ chatId, otherUserId, loginUserId, goBack }) => {
    const [message, setMessage] = useState('');
    const [messages, setMessages] = useState([]);
    const stompClient = useRef(null);

    useEffect(() => {
        // WebSocket 연결 설정
        const socket = new SockJS('http://localhost:8080/ws');
        stompClient.current = new Client({
            webSocketFactory: () => socket,
            onConnect: () => {
                // 메시지를 수신하는 구독 설정
                stompClient.current.subscribe('/topic/chats', (msg) => {
                    if (msg.body) {
                        const receivedMessage = JSON.parse(msg.body);
                        setMessages((prevMessages) => [...prevMessages, receivedMessage]);
                    }
                });
            },
        });

        stompClient.current.activate();

        // 기존 메시지 로드
        fetch(`http://localhost:8080/api/messages/${chatId}`)
            .then((response) => response.json())
            .then((data) => {
                setMessages(data);
            })
            .catch((error) => console.error('Error:', error));

        return () => {
            // 컴포넌트 언마운트 시 WebSocket 연결 해제
            if (stompClient.current) {
                stompClient.current.deactivate();
            }
        };
    }, [chatId]);

    const handleSend = () => {
        if (message.trim() !== '') {
            const newMessage = {
                headerId: chatId,
                fromId: loginUserId,
                toId: otherUserId,
                content: message.trim(),
                time: new Date().toISOString(), // 현재 시간을 ISO 형식으로 설정
            };
            setMessages([...messages, newMessage]);
            setMessage('');

            // 메시지를 서버에 저장
            fetch('http://localhost:8080/api/messages', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(newMessage),
            })
                .then((response) => response.json())
                .then((data) => {
                    // WebSocket을 통해 새 메시지를 브로드캐스트합니다.
                    stompClient.current.publish({
                        destination: `/app/chat/${chatId}`,
                        body: JSON.stringify(data),
                    });
                })
                .catch((error) => console.error('Error:', error));
        }
    };

    return (
        <Container style={{ position: 'relative', height: '100vh', padding: '0' }}>
            <Button style={{ fontSize: '10px', margin: '10px' }} color="secondary" onClick={goBack}>
                뒤로가기
            </Button>
            <p style={{ marginLeft: '10px' }}>
                채팅방 ID: {chatId}, 상대방 ID: {otherUserId}, 내 ID: {loginUserId}
            </p>
            <div
                style={{
                    position: 'absolute',
                    top: '60px',
                    left: '0',
                    right: '0',
                    bottom: '60px',
                    overflowY: 'auto',
                    padding: '10px',
                }}
            >
                {messages.map((msg) => (
                    <div
                        key={msg.id}
                        style={{
                            display: 'flex',
                            justifyContent: msg.fromId === loginUserId ? 'flex-end' : 'flex-start',
                            marginBottom: '10px',
                        }}
                    >
                        <div
                            style={{
                                maxWidth: '60%',
                                padding: '10px',
                                borderRadius: '10px',
                                background: msg.fromId === loginUserId ? '#007bff' : '#f1f0f0',
                                color: msg.fromId === loginUserId ? '#fff' : '#000',
                                wordWrap: 'break-word',
                            }}
                        >
                            {msg.content}
                        </div>
                    </div>
                ))}
            </div>
            <div
                style={{
                    position: 'absolute',
                    bottom: '0',
                    left: '0',
                    width: '100%',
                    padding: '10px',
                    backgroundColor: '#fff',
                    borderTop: '1px solid #ccc',
                }}
            >
                <InputGroup>
                    <Input
                        type="text"
                        value={message}
                        onChange={(e) => setMessage(e.target.value)}
                        placeholder="메시지를 입력하세요"
                    />
                    <InputGroupText>
                        <Button color="primary" onClick={handleSend}>
                            전송
                        </Button>
                    </InputGroupText>
                </InputGroup>
            </div>
        </Container>
    );
};

export default ChatRoom;
